/**
 * The process's connection to the server of one pool, from xnvme_fs_connect()
 */
class session {
      public:
	explicit session(struct ::xnvme_fs_session *ptr) noexcept : ptr_(ptr) {}

	/// The raw pointer, still owned by this
	struct ::xnvme_fs_session *
	native_handle() const noexcept
	{
		return ptr_.get();
	}

	/**
	 * Opens 'name' with the XNVME_FS_O_* in 'flags'; sets '*f' to the file, or to NULL where
	 * the call fails
	 *
	 * @param name The name of the file in the pool
	 * @param flags Bits of XNVME_FS_O_*
	 * @throws std::system_error xnvme_fs_open() returns: 0 on success, a negative errno on
	 * failure
	 */
	file
	open(const std::string &name, uint32_t flags);

	/**
	 * Fills 'st' for 'name'; 0 also where there is no such name, with st->kind 0
	 *
	 * @note In this signature: 'st' is returned.
	 * @param name The name in the pool
	 * @throws std::system_error xnvme_fs_stat() returns: 0 on success, also where there is no
	 * such name, a negative errno on failure
	 */
	struct ::xnvme_fs_stat
	stat(const std::string &name);

	/**
	 * Fills 'entries' with the entries of 'directory', "" for the top, from the 'offset'th on,
	 * in the order of their names
	 *
	 * A caller iterates by calling again with 'offset' advanced by 'count' until 'remaining'
	 * is 0. The server returns at most 4096 entries a call, so 'count' may be less than 'max'
	 * while 'remaining' is not 0; 'max' 0 gives the number of entries in 'remaining', and
	 * 'entries' may then be NULL.
	 *
	 * Names added, removed or renamed between two calls shift the offsets. Pass 'version' 0 on
	 * the first call: it is set to the version of the pool's names, and a later call given
	 * that version fails with -ESTALE once the names have changed, so the caller can start
	 * over. The size of a file this process has open is the size it has here, as
	 * xnvme_fs_stat() gives.
	 *
	 * @note In this signature: 'max' is the size of 'entries'; 'count' is the size of the part
	 * of 'entries' returned; 'remaining' is returned.
	 * @param directory The directory, "" for the top
	 * @param offset The number of entries to skip
	 * @param entries The entries, as many as 'count'
	 * @param version 0, or the version a previous call set
	 * @throws std::system_error xnvme_fs_list() returns: 0 on success, -ENOENT where there is
	 * no such directory, -ESTALE where the names changed since 'version', or another negative
	 * errno
	 */
	std::tuple<detail::span<struct ::xnvme_fs_entry>, uint64_t>
	list(const std::string &directory, uint64_t offset,
	     detail::span<struct ::xnvme_fs_entry> entries, uint64_t &version);

	/**
	 * Makes the directory 'name'; 0 also where the directory exists
	 *
	 * @param name The name of the directory in the pool
	 * @throws std::system_error xnvme_fs_mkdir() returns: 0 on success, -EEXIST where 'name'
	 * is a file, or another negative errno
	 */
	void
	mkdir(const std::string &name);

	/**
	 * Removes the directory 'name' and every file and directory under it; -EBUSY where another
	 * process has one of the files open
	 *
	 * @param name The name of the directory in the pool
	 * @throws std::system_error xnvme_fs_rmdir() returns: 0 on success, -EBUSY where another
	 * process has one of the files open, or another negative errno
	 */
	void
	rmdir(const std::string &name);

	/**
	 * Removes the file 'name'; -EBUSY where another process has it open
	 *
	 * @param name The name of the file in the pool
	 * @throws std::system_error xnvme_fs_remove() returns: 0 on success, -EBUSY where another
	 * process has the file open, or another negative errno
	 */
	void
	remove(const std::string &name);

	/**
	 * Renames the file 'from' to 'to'; a file this process has open under 'from' is then 'to'
	 *
	 * @param from The name the file has
	 * @param to The name the file gets
	 * @throws std::system_error xnvme_fs_rename() returns: 0 on success, a negative errno on
	 * failure
	 */
	void
	rename(const std::string &from, const std::string &to);

	/**
	 * Fills 'info' with the pool as its server holds it
	 *
	 * @note In this signature: 'info' is returned.
	 * @throws std::system_error xnvme_fs_info() returns: 0 on success, a negative errno on
	 * failure
	 */
	struct ::xnvme_fs_info
	info();

	/**
	 * Fills 'members' with the pool's members, from the 'offset'th on, in the order of the
	 * pool
	 *
	 * As xnvme_fs_list() pages a directory; the members do not change while the pool is
	 * served, so there is no version. xnvme_fs_info() gives their number as 'nmembers'.
	 *
	 * @note In this signature: 'count' is the size of the part of 'members' returned.
	 * @param offset The number of members to skip
	 * @param members The members, as many as 'count'
	 * @throws std::system_error xnvme_fs_members() returns: 0 on success, a negative errno on
	 * failure
	 */
	std::tuple<detail::span<struct ::xnvme_fs_member>, uint64_t>
	members(uint64_t offset, detail::span<struct ::xnvme_fs_member> members);

	/**
	 * The pool's block size, which a direct read's offset and length are multiples of
	 *
	 * @return The block size in bytes
	 */
	uint32_t
	block_size();

	/**
	 * Memory the drives transfer to and from themselves, from the HOMI serving the pool, for
	 * xnvme_fs_dma_free() to free; NULL with errno set where there is none
	 *
	 * @param nbytes The number of bytes
	 * @return The memory, NULL with errno set where there is none
	 */
	void *
	dma_alloc(uint64_t nbytes);

	/**
	 * Frees 'p', memory that xnvme_fs_dma_alloc() returned for 's'
	 *
	 * @param p The memory
	 */
	void
	dma_free(void *p);

	/**
	 * Makes the dma-buf 'fd', another device's memory such as a GPU's, a direct read's
	 * destination under the range of addresses at 'vaddr', of the dma-buf's size, which the
	 * caller reserves (an mmap of PROT_NONE) and never touches. Returns -ENOTSUP where xnvme
	 * fs was built with an xNVMe that does not register dma-bufs. The fd may be closed after;
	 * unregister before the exporter frees the memory.
	 *
	 * @param fd The dma-buf
	 * @param vaddr The start of the range of addresses reserved for the dma-buf
	 * @throws std::system_error xnvme_fs_register_dmabuf() returns: 0 on success, -ENOTSUP
	 * where the xNVMe built in registers no dma-bufs, or another negative errno
	 */
	void
	register_dmabuf(int fd, void *vaddr);

	/**
	 * Ends the registration that xnvme_fs_register_dmabuf() made under 'vaddr'
	 *
	 * @param vaddr The start of the range of addresses, as given when registering
	 * @throws std::system_error xnvme_fs_unregister_dmabuf() returns: 0 on success, -ENOTSUP
	 * where the xNVMe built in registers no dma-bufs, or another negative errno
	 */
	void
	unregister_dmabuf(void *vaddr);

	/**
	 * Frees 's'. Every request submitted on a file of 's' must be done before the call
	 */
	void
	disconnect();

      private:
	struct deleter {
		void
		operator()(struct ::xnvme_fs_session *ptr) const noexcept
		{
			(void)::xnvme_fs_disconnect(ptr);
		}
	};
	std::unique_ptr<struct ::xnvme_fs_session, deleter> ptr_;
};

/**
 * A file of the pool that this process has open, from xnvme_fs_open()
 */
class file {
      public:
	explicit file(struct ::xnvme_fs_file *ptr) noexcept : ptr_(ptr) {}

	/// The raw pointer, still owned by this
	struct ::xnvme_fs_file *
	native_handle() const noexcept
	{
		return ptr_.get();
	}

	/**
	 * The size of the file in bytes as this process has it, appends held in memory included
	 *
	 * @throws std::system_error xnvme_fs_size() returns: The size, or a negative errno
	 */
	std::size_t
	size();

	/**
	 * Reads up to 'nbytes' bytes of the file from 'offset' into 'buf', and waits for them
	 *
	 * @note In this signature: 'nbytes' is the size of 'buf'.
	 * @param buf Where the bytes are read to
	 * @param offset Where in the file the read starts
	 * @throws std::system_error xnvme_fs_pread() returns: The number of bytes read, fewer than
	 * 'nbytes' at the end of the file, or a negative errno
	 */
	detail::span<std::byte>
	pread(detail::span<std::byte> buf, uint64_t offset);

	/**
	 * Writes the 'nbytes' bytes of 'buf' to the file at 'offset', and waits for them; where
	 * XNVME_FS_APPEND_BUFFER is set, an append shorter than a command is held in memory
	 * instead, for xnvme_fs_fsync() or xnvme_fs_close() to write
	 *
	 * @note In this signature: 'nbytes' is the size of 'buf'.
	 * @param buf The bytes to write
	 * @param offset Where in the file the write starts
	 * @throws std::system_error xnvme_fs_pwrite() returns: 'nbytes', or a negative errno
	 */
	std::size_t
	pwrite(detail::span<const std::byte> buf, uint64_t offset);

	/**
	 * Makes the file's data and size durable
	 *
	 * @throws std::system_error xnvme_fs_fsync() returns: 0 on success, a negative errno on
	 * failure
	 */
	void
	fsync();

	/**
	 * Sets the size of the file to 'size' bytes, after writing the appends held in memory: the
	 * bytes past a smaller size are gone, and those up to a larger size read as zeros
	 *
	 * @param size The size in bytes
	 * @throws std::system_error xnvme_fs_ftruncate() returns: 0 on success, a negative errno
	 * on failure
	 */
	void
	ftruncate(uint64_t size);

	/**
	 * Starts a read ('write' 0) or a write; a read's buffer must stay valid until the request
	 * is done
	 *
	 * The request is done once xnvme_fs_poll() sets 'done' to 1 or xnvme_fs_wait() returns. It
	 * must be done before it is submitted again or freed, before xnvme_fs_close() of 'f', and
	 * before xnvme_fs_disconnect() of the session. A request that could not be started is
	 * done, and xnvme_fs_wait() returns why.
	 *
	 * @param r The request, which is done or was never submitted
	 * @param write 0 for a read, anything else for a write
	 * @param buf Where the bytes of a read go, once the request is done, or the bytes of a
	 * write
	 * @param nbytes The number of bytes to read or write
	 * @param offset Where in the file the read or write starts
	 * @throws std::system_error xnvme_fs_submit() returns: 0 on success, a negative errno on
	 * failure
	 */
	void
	submit(req &r, int write, void *buf, uint64_t nbytes, uint64_t offset);

	/**
	 * Starts a read straight into 'dma', xnvme_fs_dma_alloc's memory or a registered
	 * dma-buf's, without the CPU touching the bytes: whole blocks of what the file holds on
	 * the drives, no hole nor appends held in memory, else the request fails with -EINVAL.
	 * Past the file's end, the last block holds what the drive does, not zeros.
	 *
	 * @param r The request, which is done or was never submitted
	 * @param dma Where the blocks are read to, once the request is done
	 * @param nbytes The number of bytes to read, a multiple of xnvme_fs_block_size()
	 * @param offset Where in the file the read starts, a multiple of xnvme_fs_block_size()
	 * @throws std::system_error xnvme_fs_submit_direct() returns: 0 on success, a negative
	 * errno on failure
	 */
	void
	submit_direct(req &r, void *dma, uint64_t nbytes, uint64_t offset);

	/**
	 * Writes the appends the file holds in memory and frees 'f' either way; returns 0, or
	 * -errno if the write failed. Every request submitted on 'f' must be done before the call
	 *
	 * @throws std::system_error xnvme_fs_close() returns: 0 on success, a negative errno where
	 * the write failed
	 */
	void
	close();

      private:
	struct deleter {
		void
		operator()(struct ::xnvme_fs_file *ptr) const noexcept
		{
			(void)::xnvme_fs_close(ptr);
		}
	};
	std::unique_ptr<struct ::xnvme_fs_file, deleter> ptr_;
};

/**
 * An asynchronous read or write, from xnvme_fs_req_new()
 */
class req {
      public:
	explicit req(struct ::xnvme_fs_req *ptr) noexcept : ptr_(ptr) {}

	/// The raw pointer, still owned by this
	struct ::xnvme_fs_req *
	native_handle() const noexcept
	{
		return ptr_.get();
	}

	/**
	 * Reaps completions without waiting, and says whether the request is done
	 *
	 * @note In this signature: 'done' is returned.
	 * @throws std::system_error xnvme_fs_poll() returns: 0 on success, a negative errno where
	 * reaping failed, -EINVAL where 'done' is NULL
	 */
	int
	poll();

	/**
	 * Waits for the request; its result, the bytes moved, or a negative errno
	 *
	 * @throws std::system_error xnvme_fs_wait() returns: The number of bytes moved, or a
	 * negative errno
	 */
	std::size_t
	wait();

	/**
	 * Frees 'r', which must be done, or never submitted
	 */
	void
	free();

      private:
	struct deleter {
		void
		operator()(struct ::xnvme_fs_req *ptr) const noexcept
		{
			(void)::xnvme_fs_req_free(ptr);
		}
	};
	std::unique_ptr<struct ::xnvme_fs_req, deleter> ptr_;
};

inline file
session::open(const std::string &name, uint32_t flags)
{
	struct ::xnvme_fs_file *f_out = nullptr;
	auto ret = ::xnvme_fs_open(ptr_.get(), name.c_str(), flags, &f_out);
	if (ret < 0) {
		throw detail::failure(static_cast<int>(-ret), "xnvme_fs_open");
	}
	return file(f_out);
}

inline struct ::xnvme_fs_stat
session::stat(const std::string &name)
{
	struct ::xnvme_fs_stat st_out{};
	auto ret = ::xnvme_fs_stat(ptr_.get(), name.c_str(), &st_out);
	if (ret < 0) {
		throw detail::failure(static_cast<int>(-ret), "xnvme_fs_stat");
	}
	return st_out;
}

inline std::tuple<detail::span<struct ::xnvme_fs_entry>, uint64_t>
session::list(const std::string &directory, uint64_t offset,
	      detail::span<struct ::xnvme_fs_entry> entries, uint64_t &version)
{
	uint32_t count_out{};
	uint64_t remaining_out{};
	auto ret = ::xnvme_fs_list(ptr_.get(), directory.c_str(), offset, entries.data(),
				   static_cast<uint32_t>(entries.size()), &count_out,
				   &remaining_out, &version);
	const auto entries_len = std::min(static_cast<std::size_t>(count_out), entries.size());
	if (ret < 0) {
		throw detail::failure(static_cast<int>(-ret), "xnvme_fs_list");
	}
	return {entries.first(entries_len), remaining_out};
}

