inline detail::span<std::byte>
file::pread(detail::span<std::byte> buf, uint64_t offset)
{
	auto ret = ::xnvme_fs_pread(ptr_.get(), buf.data(), static_cast<uint64_t>(buf.size()),
				    offset);
	const auto buf_len = std::min(static_cast<std::size_t>(ret), buf.size());
	if (ret < 0) {
		throw detail::failure(static_cast<int>(-ret), "xnvme_fs_pread");
	}
	return buf.first(buf_len);
}

