file::pwrite(detail::span<const std::byte> buf, uint64_t offset)
{
	auto ret = ::xnvme_fs_pwrite(ptr_.get(), buf.data(), buf.size(), offset);
	if (ret < 0) {
		throw detail::failure(static_cast<int>(-ret), "xnvme_fs_pwrite");
	}
	return static_cast<std::size_t>(ret);
}

