req::wait()
{
	auto ret = ::xnvme_fs_wait(ptr_.get());
	if (ret < 0) {
		throw detail::failure(static_cast<int>(-ret), "xnvme_fs_wait");
	}
	return static_cast<std::size_t>(ret);
}

inline void
req::free()
{
	ptr_.reset();
}

/**
 * Connects to the server of 'pool' at '<socket_dir>/<pool>.sock', its members reached with
 * 'backend', one of upcie, io_uring, io_uring_direct and io_uring_cmd, and upcie through HOMI
 * 'homi_id'; a NULL or empty 'backend' is XNVME_FS_BACKEND's, else upcie. Sets '*s' to the
 * session, or to NULL where the call fails
 *
 * @param pool The name of the pool
 * @param socket_dir The directory that holds the socket of the pool's server
 * @param backend How the members are reached, NULL or "" for the default
 * @param homi_id The HOMI that upcie reaches the members through
 * @throws std::system_error xnvme_fs_connect() returns: 0 on success, a negative errno on failure
 */
inline session
connect(const std::string &pool, const std::string &socket_dir, const char *backend,
	uint32_t homi_id)
{
	struct ::xnvme_fs_session *s_out = nullptr;
	auto ret = ::xnvme_fs_connect(pool.c_str(), socket_dir.c_str(), backend, homi_id, &s_out);
	if (ret < 0) {
		throw detail::failure(static_cast<int>(-ret), "xnvme_fs_connect");
	}
	return session(s_out);
}

/**
 * Makes a request, which a submit starts, and may start again once the request is done
 *
 * @note In this signature: 'r' is returned.
 * @throws std::system_error xnvme_fs_req_new() returns: 0 on success, -ENOMEM where there is no
 * memory, -EINVAL where 'r' is NULL
 */
inline req
req_new()
{
	struct ::xnvme_fs_req *r_out = nullptr;
	auto ret = ::xnvme_fs_req_new(&r_out);
	if (ret < 0) {
		throw detail::failure(static_cast<int>(-ret), "xnvme_fs_req_new");
	}
	return req(r_out);
}

/**
 * The message of the call on this thread that failed last, or "" where none has
 *
 * The pointer is to storage of the calling thread, the same on every call: it stays valid until
 * the thread exits, and holds this message until the next call that fails on the thread. A call
 * that succeeds leaves the message as it was.
 */
inline std::string_view
errmsg()
{
	auto ret = ::xnvme_fs_errmsg();
	return std::string_view(ret);
}

